(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const report = () => JSON.stringify({
    url: location.href,
    radios: Array.from(document.querySelectorAll('input[type=radio]')).filter(i=>i.offsetParent!==null).map(i=>i.id+':'+i.checked).slice(0,8),
    visBtns: Array.from(document.querySelectorAll('button')).filter(b=>b.offsetParent!==null).map(b=>(b.innerText||'').replace(/\s+/g,' ').trim()).filter(Boolean).filter(t=>/login|continue|proceed|confirm|send|otp|web|trader|try/i.test(t)).slice(0,10),
    otpVals: Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null && /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||'')).map(i=>i.value),
    errs: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/wrong|invalid|incorrect|expired|failed|mismatch|not found/i.test(t) && t.length<100).slice(0,4))
  });
  try {
    const tab = Array.from(document.querySelectorAll('button')).find(b => /login with client id/i.test((b.innerText||'').replace(/\s+/g,' ').trim()));
    if (tab) tab.click();
    await sleep(1000);
    const ci = document.getElementById('fy_client_id');
    if (ci) {
      const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
      setter.call(ci, 'YA38754');
      ci.dispatchEvent(new Event('input', {bubbles:true}));
      ci.dispatchEvent(new Event('change', {bubbles:true}));
      await sleep(300);
      const cont = Array.from(document.querySelectorAll('button')).find(b => /^continue/i.test((b.innerText||'').replace(/\s+/g,' ').trim()) && b.offsetParent!==null);
      if (cont) cont.click();
      await sleep(7000);
    }
    const boxes = Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null && /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||''));
    if (boxes.length) {
      const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
      const digits = '978963';
      for (let i=0;i<boxes.length;i++){
        setter.call(boxes[i], i < digits.length ? digits[i] : '');
        boxes[i].dispatchEvent(new Event('input', {bubbles:true}));
        boxes[i].dispatchEvent(new Event('change', {bubbles:true}));
      }
      await sleep(400);
      const cfm = Array.from(document.querySelectorAll('button')).find(b => /confirm\s*otp/i.test((b.innerText||'').replace(/\s+/g,' ')) && b.offsetParent!==null);
      if (cfm) cfm.click();
      await sleep(9000);
    }
    const web = document.getElementById('main_web_rd');
    if (web) { try { web.click(); } catch(e){} await sleep(600); }
    let clickedSubmit = '';
    const modalSubmit = Array.from(document.querySelectorAll('button')).filter(b=>b.offsetParent!==null)
      .find(b => /^(login|continue|proceed|done)$/i.test((b.innerText||'').replace(/\s+/g,' ').trim()));
    if (modalSubmit) { modalSubmit.click(); clickedSubmit = (modalSubmit.innerText||'').replace(/\s+/g,' ').trim(); await sleep(9000); }
    return JSON.stringify({clickedSubmit, ...JSON.parse(report())});
  } catch(e) {
    return JSON.stringify({stage:'error', msg:String(e), ...JSON.parse(report())});
  }
})()
